<script setup>
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue';
import PhoneSettings from './PhoneSettings.vue';
import GlassAppearance from './desktop/GlassAppearance.vue';
import {useGlass} from './desktop/useGlass.js';
import DesktopSidebar from './desktop/DesktopSidebar.vue';
import CaptureStatus from './desktop/CaptureStatus.vue';
import SettingsNavigation from './desktop/SettingsNavigation.vue';
import DownloadRow from './desktop/DownloadRow.vue';
import {activeStatus,matchesQuery,sortResources,filterJobs,normalizedSettings,shortcutAction} from './desktop/selectors.js';
import {size,percent,jobLabel,duration,eta} from './desktop/formatters.js';
import {Search,Download,Settings,BookOpen,Link2,Play,Pause,Square,Trash2,ExternalLink,FolderOpen,Video,Image,Music,File,Copy,X,Check,ShieldCheck,ShieldAlert,ChevronRight,RefreshCw,Plus,CheckCircle2,AlertCircle,LoaderCircle,Network,ArrowDownToLine,ListChecks,Eye,Pencil,Layers,Upload,Stethoscope,HardDrive,RotateCcw,ChevronDown,CheckCheck,Gauge,ArrowDownWideNarrow} from 'lucide-vue-next';
const page=ref('capture'),state=ref({resources:[],jobs:[],batches:[],config:{downloadDir:'',proxyPort:18999,segments:8,concurrent:3,https:true,hostFilter:'',classifyBy:'none',nameTemplate:'{title}',duplicatePolicy:'ask',updateUrl:'',onboardingDone:true},capture:false,certificateInstalled:false,proxyAddress:'127.0.0.1:18999'});
const {appearance,systemMotion,systemTransparency,reducedMotion,reducedTransparency,background,glassStyle,pointerMove,clearHighlight,resetAppearance}=useGlass();
const nativeDesktop=!!window.go?.main?.App?.Bootstrap;
const isMac=computed(()=>state.value.platform==='darwin');
const platformName=computed(()=>isMac.value?'macOS':'Windows');
const loaded=ref(false),connectionError=ref(''),query=ref(''),type=ref('all'),selected=ref(''),checked=ref([]),jobChecked=ref([]),modal=ref(''),urlInput=ref(''),busy=ref(false),message=ref(''),messageError=ref(false),form=ref({}),confirmAction=ref(''),jobFilter=ref('all');
const jobQuery=ref(''),resourceSort=ref('recent'),settingsTab=ref('files');
const settingsDirty=computed(()=>loaded.value&&JSON.stringify(normalizedSettings(form.value))!==JSON.stringify(normalizedSettings(state.value.config)));
const batchExpanded=ref(''),groupResources=ref(true),qualityByResource=ref({}),formatsByResource=ref({}),formatLoading=ref(false),formatError=ref(''),posterCache=ref({}),posterUnavailable=ref({}),previewData=ref(null),previewError=ref(''),previewLoading=ref(false);
const duplicateRequests=ref([]),renameMode=ref('resources'),renameTemplate=ref('{title}'),maintenanceBusy=ref(''),cacheInfo=ref(null),selfCheck=ref(null),updateInfo=ref(null),localUpdatePath=ref(''),onboardingStep=ref(0);
const wechatStatus=ref(null),checkingWechat=ref(false),wechatQuality=ref(savedWechatQuality());
function savedWechatQuality(){try{const value=localStorage.getItem('resourcelens.wechatQuality');return ['best','source','playback'].includes(value)?value:'best'}catch{return 'best'}}
watch(wechatQuality,value=>{try{localStorage.setItem('resourcelens.wechatQuality',value)}catch{}});
let base='',token='',poll,timer,wechatCheckedAt=0,firstRefresh=true,posterRunning=false,disposed=false;
const nav=[{id:'capture',label:'资源捕获',icon:Search},{id:'downloads',label:'下载任务',icon:Download},{id:'settings',label:'设置',icon:Settings},{id:'help',label:'使用帮助',icon:BookOpen}];
const types=[{id:'all',label:'全部'},{id:'video',label:'视频'},{id:'audio',label:'音频'},{id:'image',label:'图片'},{id:'other',label:'其他'}];
const labels={video:'视频',audio:'音频',image:'图片',playlist:'清单',file:'文件',other:'其他'},icons={video:Video,audio:Music,image:Image,playlist:ListChecks,file:File,other:File};
const resourceIndex=computed(()=>new Map(state.value.resources.map(r=>[r.id,r])));
const filtered=computed(()=>state.value.resources.filter(r=>(type.value==='all'||(type.value==='other'?!['video','audio','image'].includes(r.type):r.type===type.value))&&matchesQuery(r,query.value,['name','url','host','author','site'])));
const groupCounts=computed(()=>{const counts={};for(const r of state.value.resources)if(r.groupId)counts[r.groupId]=(counts[r.groupId]||0)+1;return counts});
const groupedSource=computed(()=>{if(!groupResources.value)return filtered.value;const groups=new Map(),ungrouped=[];for(const r of filtered.value){if(!r.groupId){ungrouped.push(r);continue}const previous=groups.get(r.groupId);const priority=v=>v.captureRequired?0:v.kind==='page'?5:v.type==='video'?4:v.type==='playlist'?3:v.type==='audio'?2:1;if(!previous||priority(r)>priority(previous))groups.set(r.groupId,r)}const ids=new Set([...ungrouped,...groups.values()].map(r=>r.id));return filtered.value.filter(r=>ids.has(r.id))});
const grouped=computed(()=>sortResources(groupedSource.value,resourceSort.value));
const resourceTypeCounts=computed(()=>Object.fromEntries(types.map(t=>[t.id,t.id==='all'?state.value.resources.length:state.value.resources.filter(r=>t.id==='other'?!['video','audio','image'].includes(r.type):r.type===t.id).length])));
const shown=computed(()=>grouped.value.slice(0,250)),current=computed(()=>state.value.resources.find(r=>r.id===selected.value));
const related=computed(()=>current.value?.groupId?state.value.resources.filter(r=>r.groupId===current.value.groupId&&r.id!==current.value.id):[]);
const currentFormats=computed(()=>current.value?(formatsByResource.value[current.value.id]||current.value.formats||[]):[]);
const activeJobs=computed(()=>state.value.jobs.filter(j=>activeStatus(j.status)).length),pausedJobs=computed(()=>state.value.jobs.filter(j=>j.status==='paused').length);
const completedJobs=computed(()=>state.value.jobs.filter(j=>j.status==='completed').length),failedJobs=computed(()=>state.value.jobs.filter(j=>j.status==='failed').length);
const totalSpeed=computed(()=>state.value.jobs.filter(j=>j.status==='downloading').reduce((sum,j)=>sum+(j.speed||0),0));
const jobFilters=computed(()=>[{id:'all',label:'全部任务',count:state.value.jobs.length},{id:'active',label:'进行中',count:activeJobs.value},{id:'paused',label:'已暂停',count:pausedJobs.value},{id:'completed',label:'已完成',count:completedJobs.value},{id:'failed',label:'失败',count:failedJobs.value}]);
const visibleJobs=computed(()=>filterJobs(state.value.jobs,jobFilter.value,jobQuery.value));
const batches=computed(()=>(state.value.batches||[]).slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).slice(0,5));
const title=computed(()=>nav.find(n=>n.id===page.value)?.label),subtitle=computed(()=>({capture:'捕获正在浏览的图片、视频与音频',downloads:'每一个资源，都有清晰的下载进度',settings:'让捕获与下载，按你的习惯工作',help:'从捕获到保存，只需要几个步骤'})[page.value]);
const renameIds=computed(()=>renameMode.value==='jobs'?jobChecked.value:checked.value);
let modalTrigger=null;
watch(modal,async(value,previous)=>{if(value&&!previous)modalTrigger=document.activeElement;await nextTick();if(value){const dialog=document.querySelector('.modal');(dialog?.querySelector('textarea,input:not([type="checkbox"]),select')||dialog?.querySelector('button:not(:disabled)'))?.focus()}else if(modalTrigger?.isConnected){modalTrigger.focus();modalTrigger=null}});
function dialogKeydown(event){if(event.key==='Escape'){event.preventDefault();closeModal();return}if(event.key!=='Tab')return;const controls=[...event.currentTarget.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')].filter(el=>el.getClientRects().length);const first=controls[0],last=controls.at(-1);if(!first){event.preventDefault();return}if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
watch([query,type],()=>{if(selected.value&&!filtered.value.some(r=>r.id===selected.value))selected.value='';void loadPosters()});
watch(selected,()=>{formatError.value='';if(current.value){void loadFormats(current.value);void loadPoster(current.value,true)}});
function toast(s,error=false){message.value=s;messageError.value=error;clearTimeout(timer);timer=setTimeout(()=>message.value='',5500)}
async function api(path,data){const response=await fetch(base+'/api/'+path,{method:data===undefined?'GET':'POST',headers:{Authorization:'Bearer '+token,...(data===undefined?{}:{'Content-Type':'application/json'})},...(data===undefined?{}:{body:JSON.stringify(data)})});const json=await response.json();if(!response.ok||!json.ok)throw Error(json.error||'请求失败');return json.data}
async function refresh(){try{if(!token){let b;if(window.go?.main?.App?.Bootstrap)b=await window.go.main.App.Bootstrap();else{const r=await fetch('/api/bootstrap');const j=await r.json();b=j.data}base=b.baseURL;token=b.token}const next=await api('state');const changed=next.capture!==state.value.capture;next.resources||=[];next.jobs||=[];next.batches||=[];state.value=next;if(next.update)updateInfo.value=next.update;connectionError.value='';if(!loaded.value){form.value={classifyBy:'none',nameTemplate:'{title}',duplicatePolicy:'ask',updateUrl:'',...next.config};loaded.value=true}if(selected.value&&!next.resources.some(r=>r.id===selected.value))selected.value='';checked.value=checked.value.filter(id=>next.resources.some(r=>r.id===id));jobChecked.value=jobChecked.value.filter(id=>next.jobs.some(j=>j.id===id));if(firstRefresh){firstRefresh=false;if(next.config.onboardingDone===false){onboardingStep.value=0;modal.value='onboarding';void checkEnvironment()}}if(page.value==='capture'){if(changed||Date.now()-wechatCheckedAt>5000)void checkWechat();void loadPosters()}}catch(e){connectionError.value='连接本地服务失败：'+e.message}}
async function checkWechat(){if(!token||checkingWechat.value)return;checkingWechat.value=true;try{wechatStatus.value=await api('wechat-status');wechatCheckedAt=Date.now()}catch(e){wechatStatus.value={code:'check-failed',message:'微信连接检查失败：'+e.message}}finally{checkingWechat.value=false}}
async function run(fn){if(busy.value)return;busy.value=true;try{await fn();await refresh()}catch(e){toast(e.message,true)}finally{busy.value=false}}
async function selectPage(id){
 if(page.value===id)return;
 page.value=id;
 if(id==='settings'){if(!settingsDirty.value)form.value={classifyBy:'none',nameTemplate:'{title}',duplicatePolicy:'ask',updateUrl:'',...state.value.config};void inspectCache()}
 if(id==='capture')void loadPosters();
 await nextTick();
}
function requestedQuality(r){return qualityByResource.value[r.id]||(r.wechatVideo?wechatQuality.value:'best')}
function resourceSize(r){const f=(formatsByResource.value[r.id]||r.formats||[]).find(f=>f.id===requestedQuality(r));if(f?.size>0)return (f.approx?'约 ':'')+size(f.size);return r.wechatVideo&&(r.wechatResolvedQuality!==requestedQuality(r)||r.size<=0)?'下载时确认':size(r.size)}
function date(v){return new Date(v).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}
function isQueued(id){return state.value.jobs.some(j=>j.resourceId===id&&activeStatus(j.status))}
function mediaInfo(r){return [r.width&&r.height?r.width+' × '+r.height:'',r.fps?r.fps+' fps':'',r.bitrate?Number(r.bitrate).toFixed(0)+' kbps':''].filter(Boolean).join(' · ')}
function formatLabel(f){return [f.label||f.id,f.width&&f.height?f.width+'×'+f.height:'',f.fps?f.fps+'fps':'',f.size>0?(f.approx?'约 ':'')+size(f.size):'',f.available===false?'不可用':''].filter(Boolean).join(' · ')}
function openAdd(){modal.value='add'}
function allCheck(event){checked.value=event.target.checked?shown.value.filter(r=>!r.captureRequired).map(r=>r.id):[]}
function allJobs(event){jobChecked.value=event.target.checked?visibleJobs.value.filter(j=>!activeStatus(j.status)&&j.status!=='paused').map(j=>j.id):[]}
async function copy(s){try{if(window.go?.main?.App?.CopyText)await window.go.main.App.CopyText(s);else await navigator.clipboard.writeText(s);toast('已复制')}catch(e){toast('复制失败：'+e.message,true)}}
function inputLinks(text){const lines=text.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);const urls=lines.flatMap(s=>/^https?:\/\/\S+$/i.test(s)?[s]:s.match(/https?:\/\/[^\s<>"'，。；、（）【】]+/gi)||[]);return [...new Set((urls.length?urls:lines).map(s=>s.replace(/[，。；、！!"'）)\]}]+$/g,'')))]}
async function addLinks(){await run(async()=>{const urls=inputLinks(urlInput.value);if(!urls.length)throw Error('请先输入链接');if(urls.length>100)throw Error('每次最多添加 100 个链接');const result=await api('batch-add',{urls});batchExpanded.value=result.id||result.batchId||result;modal.value='';urlInput.value='';page.value='capture';toast(`已提交 ${urls.length} 个链接，正在后台解析`)})}
function batchCounts(b){const items=b.items||[];return {total:items.length,ready:items.filter(i=>i.status==='ready').length,failed:items.filter(i=>i.status==='failed').length,active:items.filter(i=>['queued','parsing'].includes(i.status)).length}}
function batchStatus(s){return {queued:'排队中',parsing:'正在解析',ready:'解析完成',completed:'已完成',failed:'解析失败',cancelled:'已取消'}[s]||s}
function selectBatch(b){checked.value=(b.items||[]).filter(i=>i.status==='ready'&&state.value.resources.some(r=>r.id===i.resourceId&&!r.captureRequired)).map(i=>i.resourceId);toast(`已选择 ${checked.value.length} 个可下载资源`)}
async function cancelBatch(b){await run(()=>api('batch-cancel',{id:b.id}))}
async function retryBatch(b,item){urlInput.value=(item?[item]:b.items||[]).filter(i=>i.status==='failed').map(i=>i.url).join('\n');if(urlInput.value)await addLinks()}
async function queueDownload(id,force=false,quality){const r=state.value.resources.find(r=>r.id===id);const q=quality||requestedQuality(r||{id});const paused=state.value.jobs.find(j=>j.resourceId===id&&j.status==='paused'&&(j.requestedQuality||'best')===q);if(paused&&!force){await api('resume',{id:paused.id});return true}const existing=state.value.jobs.find(j=>j.resourceId===id&&j.status==='completed');try{const result=await api('download',{id,quality:q,force});if(existing&&result===existing.id&&!force){toast('已跳过重复内容，保留已有文件');return false}return true}catch(e){if(e.message.startsWith('DUPLICATE:')){duplicateRequests.value.push({id,name:r?.name||'资源',quality:q,message:e.message.slice(10).trim(),jobId:existing?.id});return false}throw e}}
async function download(id){await run(async()=>{duplicateRequests.value=[];if(await queueDownload(id))toast('已加入下载队列');if(duplicateRequests.value.length)modal.value='duplicate'})}
async function batchDownload(){await run(async()=>{duplicateRequests.value=[];let count=0;const failures=[];for(const id of checked.value){if(!isQueued(id)&&!state.value.resources.find(r=>r.id===id)?.captureRequired){try{if(await queueDownload(id))count++}catch(e){failures.push(e.message)}}}toast(`已加入 ${count} 个下载任务`+(failures.length?`，${failures.length} 个未能加入：${failures[0]}`:''),!!failures.length);page.value='downloads';if(duplicateRequests.value.length)modal.value='duplicate'})}
async function forceDuplicates(){await run(async()=>{let count=0;for(const item of duplicateRequests.value)if(await queueDownload(item.id,true,item.quality))count++;duplicateRequests.value=[];modal.value='';toast(`已重新加入 ${count} 个下载任务`)})}
async function locateDuplicate(item){modal.value='';page.value='downloads';jobFilter.value='completed';if(item.jobId){await nextTick();document.querySelector('[data-job-id="'+item.jobId+'"]')?.scrollIntoView({block:'center'});await openFolder(item.jobId)}}
async function cancel(id){await run(async()=>{await api('cancel',{id});toast('正在取消任务')})}
async function pauseJob(id){await run(async()=>{await api('pause',{id});toast('已暂停，下载进度已保留')})}
async function resumeJob(j){await run(async()=>{if(j.status==='paused'||j.resumeAvailable){await api('resume',{id:j.id});toast('已加入续传队列')}else{duplicateRequests.value=[];await queueDownload(j.resourceId,false,j.requestedQuality);if(duplicateRequests.value.length)modal.value='duplicate';else toast('已加入重试队列')}})}
function openRename(mode){renameMode.value=mode;renameTemplate.value=state.value.config.nameTemplate||'{title}';modal.value='rename'}
async function renameSelected(){await run(async()=>{if(!renameTemplate.value.trim())throw Error('请输入命名模板');const result=await api('rename',{ids:renameIds.value,template:renameTemplate.value,mode:renameMode.value});modal.value='';toast(`已重命名 ${typeof result==='number'?result:result?.count??renameIds.value.length} 项`)})}
function exportLinks(){const list=checked.value.length?state.value.resources.filter(r=>checked.value.includes(r.id)):filtered.value;if(!list.length){toast('没有可导出的资源');return}const blob=new Blob([list.map(r=>r.url).join('\r\n')],{type:'text/plain;charset=utf-8'});const href=URL.createObjectURL(blob);const a=document.createElement('a');a.href=href;a.download='拾流-资源链接.txt';a.click();setTimeout(()=>URL.revokeObjectURL(href),3000);toast(`已导出 ${list.length} 个链接`)}
function ask(action){confirmAction.value=action;modal.value='confirm'}
async function confirm(){await run(async()=>{if(confirmAction.value==='clear'){await api('clear',{});toast('资源列表已清空')}else if(confirmAction.value==='history'){await api('clear-jobs',{ids:jobChecked.value});jobChecked.value=[];toast('已移除所选任务记录，文件保留')}else if(confirmAction.value==='certificate'){await api('install-certificate',{});toast('HTTPS 证书已安装')}else if(confirmAction.value==='removeCertificate'){await api('remove-certificate',{});toast('已移除拾流证书')}else if(confirmAction.value==='capture'){if(state.value.config.https&&!state.value.certificateInstalled)await api('install-certificate',{});await api('capture',{enabled:true});toast('已开始捕获，系统代理已临时切换')}else if(confirmAction.value==='update-install'){await api('update-install',{});toast(isMac.value?'DMG 已打开，拾流即将退出；请将应用拖入 Applications':'已启动升级程序，请按安装向导完成升级')}else if(confirmAction.value==='update-rollback'){await api('update-rollback',{});toast('已启动版本回滚，软件将重新启动')}modal.value=''})}
async function toggleCapture(){if(state.value.capture){await run(async()=>{await api('capture',{enabled:false});toast('已停止捕获，原系统代理已恢复')})}else ask('capture')}
async function toggleMobile(enabled){await run(async()=>{await api('mobile-enable',{enabled});toast(enabled?'手机连接已开启':'手机连接已停止')})}
async function rotateMobile(){await run(async()=>{await api('mobile-code',{});toast('配对码已更新')})}
async function saveSettings(){await run(async()=>{await api('config',{config:normalizedSettings(form.value)});await refresh();form.value={...state.value.config};toast('设置已保存')})}
async function chooseDir(){if(window.go?.main?.App?.ChooseDirectory){const p=await window.go.main.App.ChooseDirectory();if(p)form.value.downloadDir=p}else toast('浏览器模式下请直接输入完整目录路径')}
async function openFolder(jobId=''){await run(()=>api('open-folder',typeof jobId==='string'&&jobId?{id:jobId}:{}))}
async function loadFormats(r){if(!r||r.captureRequired||!['video','playlist'].includes(r.type))return;formatLoading.value=true;const id=r.id;try{const result=await api('formats',{id});formatsByResource.value[id]=Array.isArray(result)?result:result?.formats||[];if(selected.value===id)formatError.value=''}catch(e){if(selected.value===id)formatError.value=e.message}finally{if(selected.value===id)formatLoading.value=false}}
function previewURL(url){return url?.startsWith('/')?base+url:url}
function jobResource(j){return resourceIndex.value.get(j.resourceId)}
function jobPoster(j){const r=jobResource(j);return r?posterUrl(r):''}
function failedJobPoster(j){const r=jobResource(j);if(r)failedPoster(r)}
function posterUrl(r){const cached=posterCache.value[r.id];return cached&&cached.expires>Date.now()?cached.url:''}
async function loadPoster(r,force=false){if(!r||!(r.thumbnail||r.type==='image')||posterUnavailable.value[r.id]&&!force||posterUrl(r)&&!force)return;try{const data=await api('preview',{id:r.id,mode:'poster'});posterCache.value[r.id]={url:previewURL(data.url),expires:Date.now()+8*60*1000};delete posterUnavailable.value[r.id]}catch{posterUnavailable.value[r.id]=true}}
async function loadPosters(){if(posterRunning||!token||page.value!=='capture')return;posterRunning=true;try{const items=shown.value.slice(0,40).filter(r=>(r.thumbnail||r.type==='image')&&!posterUrl(r)&&!posterUnavailable.value[r.id]);for(let i=0;i<items.length&&!disposed;i+=2)await Promise.allSettled(items.slice(i,i+2).map(r=>loadPoster(r)))}finally{posterRunning=false}}
function failedPoster(r){delete posterCache.value[r.id];posterUnavailable.value[r.id]=true}
let previewRequest=0;
async function openPreview(id,mode='video'){const request=++previewRequest;previewData.value=null;previewError.value='';previewLoading.value=true;modal.value='preview';try{const data=await api('preview',{id,mode});if(request===previewRequest&&modal.value==='preview')previewData.value={...data,url:previewURL(data.url)}}catch(e){if(request===previewRequest)previewError.value=e.message}finally{if(request===previewRequest)previewLoading.value=false}}
function previewMetadata(event){const video=event.target;if(modal.value==='preview'&&(!video.videoWidth||!video.videoHeight))previewError.value='当前播放源没有可解码的画面。请下载完成后再次预览，软件会自动准备兼容播放版本。'}
function closeModal(){if(busy.value)return;++previewRequest;modal.value='';previewData.value=null;previewLoading.value=false}
async function maintenance(key,fn){if(maintenanceBusy.value)return;maintenanceBusy.value=key;try{await fn()}catch(e){toast(e.message,true)}finally{maintenanceBusy.value=''}}
async function inspectCache(){if(!token)return;try{cacheInfo.value=await api('cache',{enabled:false})}catch{}}
async function cleanCache(){await maintenance('cache',async()=>{const before=cacheInfo.value;cacheInfo.value=await api('cache',{enabled:true});toast(`清理完成，释放 ${size(cacheInfo.value.removedBytes??Math.max(0,(before?.bytes||0)-(cacheInfo.value.bytes||0)))}`)})}
async function checkEnvironment(){await maintenance('check',async()=>{selfCheck.value=await api('self-check',{})})}
async function exportDiagnostics(){await maintenance('diagnostics',async()=>{const result=await api('diagnostics',{});toast(result.message||'已导出故障信息：'+(result.file||result.path||''))})}
async function chooseUpdate(){if(window.go?.main?.App?.ChooseUpdateFile){try{const p=await window.go.main.App.ChooseUpdateFile();if(p){localUpdatePath.value=p;await prepareLocalUpdate()}}catch(e){toast(e.message,true)}}else toast('请在下方输入新版安装包的完整路径')}
async function prepareLocalUpdate(){await maintenance('update-local',async()=>{if(!localUpdatePath.value.trim())throw Error('请选择或输入安装包路径');updateInfo.value=await api('update-local',{path:localUpdatePath.value.trim()});toast(updateInfo.value.message||'本地升级包已准备好')})}
async function checkUpdates(){await maintenance('update-check',async()=>{await api('config',{config:{...form.value,segments:Number(form.value.segments),concurrent:Number(form.value.concurrent)}});updateInfo.value=await api('update-check',{});toast(updateInfo.value.message||'更新检查完成')})}
async function downloadUpdate(){await maintenance('update-download',async()=>{updateInfo.value=await api('update-download',{});toast(updateInfo.value.message||'更新包已准备好')})}
async function finishOnboarding(){await run(async()=>{await api('onboarding',{});modal.value='';toast('设置完成，可以开始添加链接或捕获资源')})}
function startOnboarding(){onboardingStep.value=0;modal.value='onboarding';void checkEnvironment()}
const confirmTitle=computed(()=>({clear:'清空资源列表？',history:'移除所选任务记录？',certificate:'安装 HTTPS 捕获证书？',removeCertificate:'移除 HTTPS 捕获证书？',capture:'开始捕获网络资源？','update-install':'开始安装更新？','update-rollback':'回滚到上一版本？'})[confirmAction.value]);
const confirmText=computed(()=>({clear:'仅移除列表记录，已下载的文件和下载任务会保留。',history:`将移除 ${jobChecked.value.length} 条任务记录，下载文件会保留。暂停和进行中的任务不能从这里移除。`,certificate:(isMac.value?'将拾流本机生成的证书加入登录钥匙串并信任 SSL；macOS 会请求钥匙串授权。':'将拾流本机生成的证书加入当前用户的受信任根证书库。')+'用于检查经过本地代理的 HTTPS 响应，你可以在设置中移除它。',removeCertificate:'移除后，HTTPS 捕获将不可用。已下载的文件会保留。',capture:'开始后，'+platformName.value+' 系统代理会临时指向拾流。停止捕获或正常退出时将恢复原设置。'+(isMac.value?' macOS 会请求网络设置授权。':'')+(state.value.config.https&&!state.value.certificateInstalled?' 本次还会安装拾流的本地 HTTPS 捕获证书。':''),'update-install':(isMac.value?'DMG 会打开，拾流随后退出。将应用拖入 Applications 替换，下载记录、配置和文件保留。':'软件会关闭并启动所选安装程序。安装时使用当前目录，保留下载记录、配置和文件。')+'请先暂停或完成正在下载的任务。','update-rollback':'恢复已备份的上一版本程序并重新启动。下载目录与本机配置保留。'})[confirmAction.value]);
function selectJob(id,value){jobChecked.value=value?[...new Set([...jobChecked.value,id])]:jobChecked.value.filter(item=>item!==id)}
async function desktopKeydown(event){
 if(event.isComposing)return;
 if(event.key==='Escape'&&!modal.value&&selected.value){selected.value='';event.preventDefault();return}
 const action=shortcutAction(event,!!modal.value);if(!action||!loaded.value)return;
 event.preventDefault();if(action==='add'){openAdd();return}
 if(action==='search'){if(!['capture','downloads'].includes(page.value))await selectPage('capture');await nextTick();document.querySelector(page.value==='downloads'?'[aria-label="搜索下载任务"]':'[aria-label="搜索资源"]')?.focus();return}
 selectPage(action);
}
onMounted(async()=>{window.addEventListener('keydown',desktopKeydown);await refresh();poll=setInterval(refresh,1400)});
onUnmounted(()=>{disposed=true;window.removeEventListener('keydown',desktopKeydown);clearInterval(poll);clearTimeout(timer)});
</script>

<template>
<div class="app-shell glass-shell" :class="{'native-glass':nativeDesktop&&(isMac||state.platform==='windows'),'native-mac-glass':nativeDesktop&&isMac,'reduce-motion':reducedMotion,'reduce-transparency':reducedTransparency,'in-background':background}" :style="glassStyle" @pointermove="pointerMove" @pointerleave="clearHighlight">
 <a class="skip-link" href="#main-content">跳到主内容</a>
 <DesktopSidebar :page="page" :active-jobs="activeJobs" :loaded="loaded" :error="connectionError" :capture="state.capture" :proxy="state.proxyAddress" :version="state.version" :platform="platformName" :inert="!!modal" @navigate="selectPage" @copy="copy"/>
 <main class="main" :class="{'has-inspector':page==='capture'&&current}" id="main-content" tabindex="-1" :aria-busy="!loaded" :inert="!!modal">
  <div class="main-content">
  <header><div><h1>{{title}}</h1><p>{{subtitle}}</p></div><div class="header-actions" v-if="page==='capture'"><button :class="{stop:state.capture}" @click="toggleCapture" :disabled="busy||!loaded"><component :is="state.capture?Square:Play" :size="17"/>{{state.capture?'停止捕获':'开始捕获'}}</button><button class="primary" @click="openAdd" :disabled="!loaded" :title="isMac?'添加链接 · ⌘N':'添加链接 · Ctrl+N'"><Plus :size="18"/>添加链接</button></div><button v-else-if="page==='downloads'" class="primary" @click="openAdd" :disabled="!loaded"><Plus :size="18"/>添加链接</button><div v-else-if="page==='settings'" class="settings-save"><span :class="{dirty:settingsDirty}" role="status"><CheckCircle2 v-if="!settingsDirty" :size="16"/>{{settingsDirty?'有未保存的更改':'已保存'}}</span><button class="primary" @click="saveSettings" :disabled="busy||!loaded||!settingsDirty"><Check :size="18"/>保存设置</button></div></header>
  <div v-if="connectionError" class="connection-error"><AlertCircle :size="18"/>{{connectionError}}<button @click="refresh"><RefreshCw :size="16"/>重试</button></div>
  <CaptureStatus v-if="page==='capture'" :capture="state.capture" :certificate-installed="state.certificateInstalled" @settings="settingsTab='capture';selectPage('settings')"/>
  <details v-if="page==='capture'" class="capture-guide"><summary><ChevronDown :size="16"/><Video :size="16"/>视频号捕获指南</summary><div class="capture-guide-content"><p>开始捕获后，在电脑版微信中打开并播放视频；出现实际视频标题后选择画质并下载。</p><div class="capture-options"><div class="quality-options"><label for="wechat-quality">视频号画质</label><select id="wechat-quality" v-model="wechatQuality" aria-label="视频号默认画质"><option value="best">最高可获取</option><option value="source">匹配平台标注大小（失败则停止）</option><option value="playback">微信当前播放版本</option></select></div><button class="text-button wechat-check" @click="checkWechat" :disabled="checkingWechat||!loaded"><RefreshCw :size="15" :class="{spin:checkingWechat}"/>检查微信连接</button><p v-if="wechatStatus&&wechatStatus.code!=='captured'" class="wechat-connection-status" role="status">{{wechatStatus.message}}</p></div></div></details>
  <div v-if="page==='capture'&&batches.length" class="batch-panel"><article v-for="b in batches" :key="b.id" class="batch-summary"><div class="batch-summary-line"><button class="text-button batch-toggle" @click="batchExpanded=batchExpanded===b.id?'':b.id"><ChevronDown :size="16" :class="{rotated:batchExpanded===b.id}"/><ListChecks :size="17"/><span>{{batchCounts(b).total}} 条链接 · {{batchCounts(b).active?'正在解析':'解析结束'}}</span></button><span class="batch-counts">成功 {{batchCounts(b).ready}} · 失败 {{batchCounts(b).failed}}<span v-if="batchCounts(b).active"> · 待处理 {{batchCounts(b).active}}</span></span><button class="text-button" @click="selectBatch(b)" :disabled="!batchCounts(b).ready">选择成功项</button><button v-if="batchCounts(b).failed" class="text-button" @click="retryBatch(b)" :disabled="busy"><RefreshCw :size="14"/>重试失败项</button><button v-if="batchCounts(b).active" class="text-button" @click="cancelBatch(b)" :disabled="busy">取消解析</button></div><div class="batch-progress"><i :style="{width:((batchCounts(b).total-batchCounts(b).active)/Math.max(1,batchCounts(b).total)*100)+'%'}"></i></div><div v-if="batchExpanded===b.id" class="batch-items"><div v-for="(item,index) in b.items" :key="index" class="batch-item"><span class="batch-item-status" :class="item.status"><LoaderCircle v-if="item.status==='parsing'" :size="13" class="spin"/>{{batchStatus(item.status)}}</span><button v-if="item.resourceId" class="text-button batch-link" @click="selected=item.resourceId">{{state.resources.find(r=>r.id===item.resourceId)?.name||item.url}}</button><span v-else class="batch-link">{{item.url}}</span><span v-if="item.error" class="batch-item-error">{{item.error}}</span><button v-if="item.status==='failed'" class="text-button" @click="retryBatch(b,item)" :disabled="busy">重试</button></div></div></article></div>
  <section v-if="page==='capture'" class="workspace" :class="{'with-detail':current}">
   <div class="resource-pane"><div class="resource-heading"><div class="type-tabs" role="group" aria-label="资源类型"><button v-for="t in types" :key="t.id" :class="{selected:type===t.id}" :aria-pressed="type===t.id" @click="type=t.id">{{t.label}}<span class="filter-count">{{resourceTypeCounts[t.id]}}</span></button></div><div class="table-actions"><button class="icon-label" :class="{selected:groupResources}" @click="groupResources=!groupResources" :aria-pressed="groupResources" aria-label="收起或展开关联资源" title="将同一内容的封面、音轨与分片收起，点击详情查看关联项"><Layers :size="17"/><span>分组</span></button><button class="icon-label" @click="exportLinks" aria-label="导出资源链接" title="导出筛选或选中的资源链接"><ExternalLink :size="17"/><span>导出</span></button><button class="icon-label" @click="ask('clear')" :disabled="!state.resources.length" aria-label="清空资源列表" title="清空列表"><Trash2 :size="17"/><span>清空</span></button></div></div><div class="table-toolbar"><label class="search"><Search :size="17"/><input v-model="query" placeholder="搜索名称、作者或网址" aria-label="搜索资源"/><button v-if="query" class="icon-button clear-search" @click="query=''" aria-label="清除资源搜索"><X :size="14"/></button></label><label class="resource-sort"><ArrowDownWideNarrow :size="16"/><select v-model="resourceSort" aria-label="资源排序"><option value="recent">最新捕获</option><option value="name">名称排序</option><option value="size">大小优先</option></select></label></div>
   <div v-if="checked.length" class="selection-bar"><span>已选择 {{checked.length}} 个资源</span><button class="primary compact" @click="batchDownload" :disabled="busy"><Download :size="16"/>下载选中</button><button class="compact" @click="openRename('resources')"><Pencil :size="14"/>批量命名</button><button class="text-button" @click="checked=[]">取消选择</button></div>
   <div class="table-scroll"><table><thead><tr><th class="check-cell"><input type="checkbox" aria-label="全选资源" :checked="shown.filter(r=>!r.captureRequired).length>0&&shown.filter(r=>!r.captureRequired).every(r=>checked.includes(r.id))" @change="allCheck"/></th><th>资源名称 / 画质</th><th class="source-col">来源</th><th>类型</th><th>大小</th><th class="operation">操作</th></tr></thead><tbody><tr v-for="r in shown" :key="r.id" :class="{chosen:selected===r.id}" @click="selected=r.id" tabindex="0" @keydown.enter="selected=r.id"><td class="check-cell" @click.stop><input type="checkbox" v-model="checked" :value="r.id" :disabled="r.captureRequired" :aria-label="'选择 '+r.name"/></td><td><div class="resource-name"><div class="resource-poster"><img v-if="posterUrl(r)" :src="posterUrl(r)" alt="" loading="lazy" @error="failedPoster(r)"/><component v-else :is="icons[r.type]||File" :size="22" :class="'media-icon '+r.type"/><span v-if="r.duration" class="poster-duration">{{duration(r.duration)}}</span></div><div class="resource-caption"><strong :title="r.name">{{r.name}}</strong><span class="resource-subtitle">{{[r.site||r.host,r.author,mediaInfo(r)||r.quality].filter(Boolean).join(' · ')||r.site||r.host}}</span><span v-if="r.groupId&&groupCounts[r.groupId]>1" class="group-tag"><Layers :size="11"/>关联 {{groupCounts[r.groupId]}} 项</span></div></div></td><td class="source-col"><span class="host" :title="r.host">{{r.site||r.host}}</span></td><td><span :class="'type-badge '+r.type"><component :is="icons[r.type]||File" :size="14"/>{{labels[r.type]||'其他'}}</span></td><td class="size-cell">{{resourceSize(r)}}</td><td class="operation"><button class="download-action" @click.stop="download(r.id)" :disabled="busy||isQueued(r.id)||r.captureRequired" :title="r.captureRequired?'先在微信中播放并捕获视频':'使用这条资源选择的画质下载'"><Download :size="17"/>{{r.captureRequired?'待捕获':isQueued(r.id)?'已排队':'下载'}}</button></td></tr></tbody></table>
   <div v-if="!loaded&&!connectionError" class="loading-state" role="status"><div v-for="n in 4" :key="n" class="skeleton-row"><i></i><div><b></b><span></span></div></div><p>正在连接本地服务…</p></div>
   <div v-else-if="!shown.length" class="empty-state"><div class="empty-visual"><svg viewBox="0 0 110 80" aria-hidden="true"><path d="M12 42c24-29 37-31 50-9s27 24 39 4M12 61c24-29 37-31 50-9s27 24 39 4" fill="none" stroke="currentColor" stroke-width="7" stroke-linecap="round"/><circle cx="82" cy="14" r="5" fill="currentColor" opacity=".35"/></svg></div><h2>{{connectionError?'本地服务暂时不可用':state.resources.length?'没有匹配的资源':'把想保存的内容，留在这里'}}</h2><p>{{connectionError?'点击上方重试，连接恢复后即可继续操作。':state.resources.length?'换个关键词或资源类型试试。':state.capture?'捕获已开启。浏览网页或播放媒体，资源会自动出现在这里。':'粘贴视频链接，或开启捕获并播放媒体。选择画质后，直接保存到本机。'}}</p><button v-if="!connectionError" class="primary" @click="openAdd" :disabled="!loaded"><Link2 :size="18"/>添加资源链接</button><span class="empty-note">HTTPS 捕获需要安装本地证书；部分应用不会使用系统代理。</span></div>
   </div><div class="table-bottom"><span>{{grouped.length}} 个{{groupResources?'资源组':'资源'}}<span v-if="grouped.length>250"> · 显示前 250 个</span></span><span>资源与任务记录保存在本机</span></div></div>

  </section>
  <div v-if="page==='downloads'" class="transfer-summary" aria-label="下载概览"><span><Download :size="17"/>{{activeJobs}} 个进行中</span><i></i><span>下载速度 <strong>{{totalSpeed>0?size(totalSpeed)+'/s':'等待传输'}}</strong></span><span v-if="failedJobs" class="transfer-attention">{{failedJobs}} 个任务需要重试</span></div>
  <section v-if="page==='downloads'" class="downloads-pane panel">
   <div class="downloads-toolbar"><div class="type-tabs" role="group" aria-label="任务状态"><button v-for="f in jobFilters" :key="f.id" :class="{selected:jobFilter===f.id}" :aria-pressed="jobFilter===f.id" @click="jobFilter=f.id">{{f.label}}<span class="filter-count">{{f.count}}</span></button></div></div>
   <div class="history-toolbar"><label class="search"><Search :size="17"/><input v-model="jobQuery" placeholder="搜索任务名称或路径" aria-label="搜索下载任务"/></label><label><input type="checkbox" aria-label="选择当前已结束任务" :checked="visibleJobs.filter(j=>!activeStatus(j.status)&&j.status!=='paused').length>0&&visibleJobs.filter(j=>!activeStatus(j.status)&&j.status!=='paused').every(j=>jobChecked.includes(j.id))" @change="allJobs"/>选择已结束任务</label><template v-if="jobChecked.length"><span>{{jobChecked.length}} 项</span><button class="compact" @click="openRename('jobs')" :disabled="busy"><Pencil :size="14"/>批量命名</button><button class="compact" @click="ask('history')" :disabled="busy"><Trash2 :size="14"/>移除记录</button><button class="text-button" @click="jobChecked=[]">取消选择</button></template><button v-else class="compact reset-filters" @click="jobQuery='';jobFilter='all'" :disabled="!jobQuery&&jobFilter==='all'">清除筛选</button></div>
   <div class="job-list">
    <div v-if="!visibleJobs.length" class="empty-state"><Download :size="48" class="empty-icon"/><h2>{{jobQuery?'没有匹配的任务':state.jobs.length?'这里还没有任务':'准备好，开始保存'}}</h2><p>{{jobQuery?'换个关键词，或清除筛选查看其他任务。':state.jobs.length?'切换任务状态，查看其他下载记录。':'在资源捕获页面选择视频和画质，下载进度会显示在这里。'}}</p><button @click="selectPage('capture')"><Search :size="18"/>前往资源捕获</button></div>
    <DownloadRow v-for="j in visibleJobs" :key="j.id" :job="j" :resource="jobResource(j)" :poster="jobPoster(j)" :checked="jobChecked.includes(j.id)" :busy="busy" @select="selectJob(j.id,$event)" @poster-error="failedJobPoster(j)" @pause="pauseJob(j.id)" @cancel="cancel(j.id)" @resume="resumeJob(j)" @preview="openPreview(j.id,'job')" @folder="openFolder(j.id)"/>

   </div>
  </section>
  <SettingsNavigation v-if="page==='settings'" v-model="settingsTab"/>
  <section v-if="page==='settings'" class="settings-pane panel"><div v-show="settingsTab==='files'" class="settings-group" id="settings-panel-files" role="tabpanel" aria-labelledby="settings-tab-files"><h2>下载与文件整理</h2><p class="settings-intro">选择保存位置、整理方式和下载速度。</p><div class="field"><label for="directory">保存位置</label><div class="input-action"><input id="directory" v-model="form.downloadDir" placeholder="完整下载目录路径"/><button @click="chooseDir"><FolderOpen :size="18"/>选择目录</button></div><p>重名文件自动编号，保留已有文件。</p></div><div class="field-grid"><div class="field"><label for="classify-by">自动分文件夹</label><select id="classify-by" v-model="form.classifyBy"><option value="none">全部保存到下载目录</option><option value="platform">按平台分类</option><option value="author">按平台 / 作者分类</option></select></div><div class="field"><label for="duplicate-policy">重复下载处理</label><select id="duplicate-policy" v-model="form.duplicatePolicy"><option value="ask">提醒我选择</option><option value="skip">跳过已经完成的内容</option><option value="allow">允许重新下载</option></select></div></div><div class="field"><label for="name-template">默认文件命名</label><input id="name-template" v-model="form.nameTemplate" placeholder="{title}"/><p>可用字段：{title} 标题、{author} 作者、{platform} 平台、{date} 日期。扩展名自动保留。</p></div><h3 class="settings-subheading">下载性能</h3><div class="field-grid"><div class="field"><label for="segments">每个文件的分段数量</label><select id="segments" v-model="form.segments"><option v-for="n in [1,2,4,8,16]" :key="n" :value="n">{{n===1?'单连接':n+' 段'}}</option></select><p>服务器支持 Range 时使用分段下载。</p></div><div class="field"><label for="concurrent">同时下载的文件数量</label><select id="concurrent" v-model="form.concurrent"><option v-for="n in 6" :key="n" :value="n">{{n}} 个文件</option></select><p>其他任务会在队列中等待。</p></div></div></div><div v-show="settingsTab==='capture'" class="settings-group" id="settings-panel-capture" role="tabpanel" aria-labelledby="settings-tab-capture"><h2>网络捕获</h2><p class="settings-intro">管理捕获范围与本地 HTTPS 证书。</p><div class="field"><label for="hostFilter">来源域名筛选</label><input id="hostFilter" v-model="form.hostFilter" placeholder="留空捕获全部，例如 example.com"/><p>仅保留域名包含该内容的媒体资源。</p></div><div class="switch-row"><div><strong>捕获 HTTPS 资源</strong><p>需要安装拾流本机证书，暂不支持证书固定的应用。</p></div><label class="switch"><input type="checkbox" v-model="form.https" aria-label="捕获 HTTPS 资源"/><span></span></label></div><div class="certificate-row"><div><component :is="state.certificateInstalled?ShieldCheck:ShieldAlert" :size="25"/><div><strong>本地 HTTPS 证书</strong><span>{{state.certificateInstalled?'已安装到当前用户证书库':'尚未安装'}}</span></div></div><button v-if="!state.certificateInstalled" @click="ask('certificate')" :disabled="busy"><ShieldCheck :size="18"/>安装证书</button><button v-else @click="ask('removeCertificate')" :disabled="busy||state.capture">移除证书</button></div><p class="certificate-path">{{state.certificatePath}}</p></div>
   <GlassAppearance v-show="settingsTab==='appearance'" v-model="appearance" :system-motion="systemMotion" :system-transparency="systemTransparency" @reset="resetAppearance"/>
   <div v-show="settingsTab==='devices'" id="settings-panel-devices" role="tabpanel" aria-labelledby="settings-tab-devices"><PhoneSettings :status="state.mobile" :busy="busy" @toggle="toggleMobile" @rotate="rotateMobile" @copy="copy"/></div>
   <div v-show="settingsTab==='maintenance'" class="settings-group" id="settings-panel-maintenance" role="tabpanel" aria-labelledby="settings-tab-maintenance"><h2>缓存与故障信息</h2><div class="maintenance-card"><div><strong>临时缓存</strong><p>{{cacheInfo?'可清理 '+size(cacheInfo.bytes)+' · '+(cacheInfo.folders||0)+' 个缓存目录':'正在统计缓存…'}}</p><p>仅清理过期缓存，暂停任务的续传数据会保留。</p></div><button @click="cleanCache" :disabled="!!maintenanceBusy"><LoaderCircle v-if="maintenanceBusy==='cache'" :size="16" class="spin"/><Trash2 v-else :size="16"/>清理缓存</button></div><div class="maintenance-actions"><button @click="checkEnvironment" :disabled="!!maintenanceBusy"><Stethoscope :size="17"/>{{maintenanceBusy==='check'?'正在检查…':'检查运行环境'}}</button><button @click="exportDiagnostics" :disabled="!!maintenanceBusy"><Upload :size="17"/>{{maintenanceBusy==='diagnostics'?'正在导出…':'导出故障信息'}}</button><button @click="startOnboarding"><BookOpen :size="17"/>重新查看使用引导</button></div><div v-if="selfCheck" class="self-check-list"><div v-for="item in selfCheck.items||selfCheck.checks||[]" :key="item.id" :class="item.status"><CheckCircle2 v-if="['ok','ready','pass'].includes(item.status)" :size="16"/><AlertCircle v-else :size="16"/><strong>{{item.label||item.name}}</strong><span>{{item.message}}</span></div></div></div>
   <div v-show="settingsTab==='updates'" class="settings-group" id="settings-panel-updates" role="tabpanel" aria-labelledby="settings-tab-updates"><h2>关于与更新</h2><p class="section-note">当前版本 {{state.version||'1.6.0'}}。选择新版安装包可在本机升级；有在线更新源后，可检查并下载新版。</p><div class="field"><label for="update-path">本地安装程序</label><div class="input-action"><input id="update-path" v-model="localUpdatePath" :placeholder="isMac?'例如 /Users/你的用户名/Downloads/ResourceLens-新版.dmg':'例如 D:\\下载\\拾流-新版-安装程序.exe'"/><button @click="chooseUpdate" :disabled="!!maintenanceBusy"><FolderOpen :size="17"/>选择新版安装包</button></div><div class="field-actions"><button class="compact" @click="prepareLocalUpdate" :disabled="!localUpdatePath||!!maintenanceBusy"><Check :size="16"/>{{maintenanceBusy==='update-local'?'检查中…':'检查本地升级包'}}</button></div></div><div class="field"><label for="update-url">在线更新源（可留空）</label><input id="update-url" v-model="form.updateUrl" placeholder="https://example.com/resourcelens/update.json"/><p>填写可信发布者提供的更新清单地址。当前没有配置时，使用本地安装包升级。</p></div><div class="maintenance-actions"><button @click="checkUpdates" :disabled="!form.updateUrl||!!maintenanceBusy"><RefreshCw :size="16"/>{{maintenanceBusy==='update-check'?'正在检查…':'保存更新源并检查'}}</button><button v-if="updateInfo?.available&&!updateInfo.canInstall" @click="downloadUpdate" :disabled="!!maintenanceBusy"><Download :size="16"/>{{maintenanceBusy==='update-download'?'正在下载…':'下载更新'}}</button><button v-if="updateInfo?.canInstall" class="primary" @click="ask('update-install')" :disabled="busy||activeJobs>0"><ArrowDownToLine :size="16"/>{{isMac?'打开 DMG 并退出':'安装已准备的更新'}}</button><button v-if="updateInfo?.canRollback" @click="ask('update-rollback')" :disabled="busy||activeJobs>0"><RotateCcw :size="16"/>回滚上一版本</button></div><div v-if="updateInfo" class="update-summary" role="status"><strong>{{updateInfo.version?'更新版本 '+updateInfo.version:'升级状态'}}</strong><p>{{updateInfo.message}}</p><span v-if="updateInfo.fileName">{{updateInfo.fileName}} · {{size(updateInfo.size)}}</span><code v-if="updateInfo.sha256">SHA256 {{updateInfo.sha256}}</code></div><p v-if="activeJobs&&updateInfo?.canInstall" class="field-note warning">请先暂停或完成进行中的下载，再安装更新。</p></div>
   <div class="settings-note"><ShieldCheck :size="17"/>停止捕获或退出时，自动恢复原系统代理。</div></section>
  <section v-if="page==='help'" class="help-pane panel"><h2>从网页到文件，三步完成</h2><div class="help-step"><b>1</b><div><h3>添加链接或开始捕获</h3><p>一次粘贴最多 100 条链接，软件会在后台逐条解析。捕获模式会临时切换 {{platformName}} 系统代理，开启 HTTPS 时安装本机生成的证书。<template v-if="isMac">macOS 会请求网络设置和钥匙串授权；停止捕获时恢复原设置。</template></p></div></div><div class="help-step"><b>2</b><div><h3>查看内容，选择画质</h3><p>点击资源，查看封面、作者、时长及关联音视频。每条视频可单独选择可用画质；部分平台预览需要先下载完成。</p></div></div><div class="help-step"><b>3</b><div><h3>下载、续传与整理</h3><p>支持暂停和继续下载，退出后保留暂停记录。下载完成可直接预览或定位文件。设置中可按平台、作者分文件夹，并设置命名模板和重复下载规则。</p></div></div><div class="keyboard-shortcuts"><h3>键盘快捷键</h3><dl><dt>添加链接</dt><dd><kbd>{{isMac?'⌘':'Ctrl'}}</kbd> <kbd>N</kbd></dd><dt>搜索资源或任务</dt><dd><kbd>{{isMac?'⌘':'Ctrl'}}</kbd> <kbd>F</kbd></dd><dt>切换页面</dt><dd><kbd>{{isMac?'⌘':'Ctrl'}}</kbd> <kbd>1–4</kbd></dd><dt>关闭详情或对话框</dt><dd><kbd>Esc</kbd></dd></dl></div><div class="help-notes"><h3>平台与升级说明</h3><ul><li>通用 HTTP / HTTPS 媒体、M3U8 / MPD 清单、B 站和抖音播放页通过解析后生成 MP4。更多平台依可访问的公开播放数据解析。</li><li>视频号需先开始捕获，再在电脑版微信打开并播放。画质取决于平台实际提供的版本，任务显示实际画质和文件大小。</li><li>文件保持获取版本的原始音视频流，合并与封装不会主动降低码率。</li><li>原链接过期可能需要重新播放或解析；软件会尝试恢复已有进度，无法续传时会说明原因。</li><li>本地更新在设置中选择安装包；在线更新源需要发布者提供。故障信息可从设置导出。</li></ul></div><div class="maintenance-actions help-actions"><button @click="startOnboarding"><BookOpen :size="17"/>查看首次使用引导</button><button @click="selectPage('settings')"><Settings :size="17"/>打开维护与升级设置</button></div><div class="about-line"><svg viewBox="0 0 56 44"><path d="M3 22C16 6 21 4 31 18S43 34 53 20M3 35C16 19 21 17 31 31S43 47 53 33" fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="round"/></svg><span>拾流 ResourceLens {{state.version||'1.6.0'}}</span><span>本机保存 · 保留所选媒体流</span></div></section>
  <footer><span>{{page==='downloads'?state.jobs.length+' 个下载任务':state.resources.length+' 个资源'}}</span><i></i><span class="footer-directory"><FolderOpen :size="17"/><span :title="state.config.downloadDir">保存位置：{{state.config.downloadDir||'连接中…'}}</span></span><button class="text-button" @click="openFolder" :disabled="!loaded"><FolderOpen :size="18"/>打开文件夹</button></footer>
  </div>
   <Transition name="inspector"><aside v-if="page==='capture'&&current" class="detail-pane"><div class="detail-title"><component :is="icons[current.type]||File" :class="'media-icon '+current.type" :size="23"/><h2>资源详情</h2><button class="icon-button" @click="selected=''" aria-label="关闭资源详情"><X :size="18"/></button></div><div class="detail-body"><button class="detail-poster" v-if="posterUrl(current)" @click="openPreview(current.id,current.type==='image'?'poster':'video')" title="预览资源"><img :src="posterUrl(current)" :alt="current.name" @error="failedPoster(current)"/><span v-if="current.type==='video'||current.type==='playlist'"><Play :size="25" fill="currentColor"/></span></button><button v-else class="detail-poster empty-poster" @click="openPreview(current.id,current.type==='image'?'poster':'video')" :aria-label="'预览 '+current.name"><component :is="icons[current.type]||File" :size="42"/><span class="empty-poster-label">点击预览{{labels[current.type]||'资源'}}</span></button><h3 class="detail-resource-name">{{current.name}}</h3><p class="detail-platform">{{current.site||current.host}}</p><div class="detail-preview-actions"><button class="compact" @click="openPreview(current.id,current.type==='image'?'poster':'video')"><Eye :size="16"/>预览{{current.type==='image'?'图片':current.type==='audio'?'音频':'视频'}}</button><span v-if="current.duration">{{duration(current.duration)}}</span></div>
    <div v-if="['video','playlist'].includes(current.type)&&!current.captureRequired" class="resource-quality"><label for="resource-quality">下载画质 <button class="icon-button" @click="loadFormats(current)" :disabled="formatLoading" aria-label="重新获取画质"><RefreshCw :size="14" :class="{spin:formatLoading}"/></button></label><select id="resource-quality" :value="requestedQuality(current)" @change="qualityByResource[current.id]=$event.target.value"><option value="best">最高可获取</option><template v-if="current.wechatVideo"><option value="source">匹配平台标注大小（失败则停止）</option><option value="playback">微信当前播放版本</option></template><option v-for="f in currentFormats.filter(f=>!['best','source','playback'].includes(f.id))" :key="f.id" :value="f.id" :disabled="f.available===false">{{formatLabel(f)}}</option></select><p v-if="formatLoading" class="field-note">正在获取可用版本…</p><p v-if="formatError" class="field-note warning">{{formatError}}</p><p class="field-note">保持所选版本的原始音视频流。</p></div>
    <dl class="essential-details"><dt>下载大小</dt><dd>{{resourceSize(current)}}</dd><dt>来源</dt><dd>{{current.site||current.host}}</dd><template v-if="current.wechatSourceSize>0"><dt>平台标注</dt><dd>{{size(current.wechatSourceSize)}}<span class="mime">标注大小与可获取版本可能不同</span></dd></template></dl><details class="media-details"><summary>更多媒体信息</summary><ul v-if="currentFormats.some(f=>f.available===false||f.reason)" class="format-reasons"><li v-for="f in currentFormats.filter(f=>f.available===false||f.reason)" :key="f.id">{{f.label||f.id}}：{{f.reason||'当前不可获取'}}</li></ul><dl><dt>类型</dt><dd><span :class="'type-badge '+current.type">{{labels[current.type]||'其他'}}</span><span class="mime">{{current.mime||'未提供 MIME 类型'}}</span></dd><template v-if="current.quality||mediaInfo(current)"><dt>已知画质</dt><dd>{{mediaInfo(current)||current.quality}}</dd></template><template v-if="current.author"><dt>作者</dt><dd>{{current.author}}</dd></template><template v-if="current.kind==='page'"><dt>保存格式</dt><dd>MP4 · 自动合并音视频并校验</dd></template><dt>捕获时间</dt><dd>{{date(current.capturedAt)}}</dd></dl></details><div v-if="related.length" class="related-resources"><label class="detail-label"><Layers :size="14"/>同一内容的关联资源 · {{related.length}}</label><button v-for="r in related.slice(0,20)" :key="r.id" @click="selected=r.id"><component :is="icons[r.type]||File" :size="14"/><span>{{r.name}}</span><small>{{labels[r.type]}}</small></button></div><details class="request-details"><summary>来源链接</summary><div class="url-box">{{current.url}}</div></details><details class="request-details"><summary>查看请求信息</summary><label class="detail-label">请求头<span>已隐藏 Cookie 与认证信息</span></label><pre>{{Object.entries(current.headers||{}).map(([k,v])=>k+': '+v).join('\n')||'没有附加请求头'}}</pre></details><p v-if="current.captureRequired" class="playlist-note">当前尚未取得完整视频信息。保持捕获开启，在电脑版微信中播放目标视频；信息补全后开放下载。</p><p v-if="current.wechatVideo&&!current.captureRequired" class="playlist-note">视频号各版本的实际大小以探测和下载结果为准。需要匹配平台标注大小时，选择对应模式。</p></div><div class="detail-footer"><button class="primary full" @click="download(current.id)" :disabled="busy||isQueued(current.id)||current.captureRequired"><ArrowDownToLine :size="20"/>{{current.captureRequired?'在微信中播放后捕获':isQueued(current.id)?'已加入下载队列':'下载到本机'}}</button><button class="full copy-link" @click="copy(current.url)"><Link2 :size="17"/>复制链接</button></div></aside></Transition>
 </main>
 <div v-if="message" class="toast" :class="{error:messageError}" role="status"><component :is="messageError?AlertCircle:CheckCircle2" :size="19"/>{{message}}</div>
 <div v-if="modal" class="modal-overlay" @click.self="closeModal" @keydown="dialogKeydown"><section class="modal" :class="{'preview-modal':modal==='preview','wide-modal':['duplicate','onboarding'].includes(modal)}" role="dialog" aria-modal="true" :aria-label="modal==='add'?'添加资源链接':modal==='preview'?'资源预览':modal==='rename'?'批量重命名':modal==='duplicate'?'发现重复下载':modal==='onboarding'?'首次使用引导':confirmTitle"><div class="modal-heading"><h2>{{modal==='add'?'批量添加链接':modal==='preview'?'资源预览':modal==='rename'?'批量重命名':modal==='duplicate'?'这些内容已经下载过':modal==='onboarding'?'开始使用拾流':confirmTitle}}</h2><button class="icon-button" @click="closeModal" :disabled="busy" aria-label="关闭对话框"><X :size="22"/></button></div>
  <template v-if="modal==='add'"><p>粘贴分享文本、视频播放页、M3U8 / MPD 清单或文件直链。每次最多 100 个链接，后台解析时可以继续使用软件。</p><textarea v-model="urlInput" placeholder="粘贴抖音 / 快手 / 小红书分享文本，或多条视频链接，每行一条" aria-label="资源链接或分享文本" :disabled="busy" autofocus></textarea><p class="modal-hint">自动提取分享文本中的链接，去除本次重复项。解析成功后可逐条选择画质或批量下载。视频号分享链接仍需在电脑版微信正常播放后捕获。</p><div class="modal-actions"><button @click="closeModal" :disabled="busy">取消</button><button class="primary" @click="addLinks" :disabled="busy||!urlInput.trim()"><LoaderCircle v-if="busy" class="spin" :size="18"/><Plus v-else :size="18"/>{{busy?'正在提交…':'开始后台解析'}}</button></div></template>
  <template v-else-if="modal==='preview'"><div v-if="previewLoading" class="preview-empty"><LoaderCircle :size="32" class="spin"/><p>正在准备预览…<br/>首次兼容处理可能需要一点时间。</p></div><div v-else-if="previewError" class="preview-empty"><AlertCircle :size="32"/><p>{{previewError}}</p></div><template v-else-if="previewData"><p class="preview-name" :title="previewData.name">{{previewData.name}}</p><p v-if="previewData.quality" class="field-note">{{previewData.quality}} · {{previewData.note||'下载仍按资源选择的画质执行。'}}</p><img v-if="previewData.type==='image'||previewData.type?.startsWith('image/')" class="preview-image" :src="previewData.url" :alt="previewData.name" @error="previewError='图片预览失败，请重新打开预览'"/><audio v-else-if="previewData.type==='audio'||previewData.type?.startsWith('audio/')" class="preview-audio" :src="previewData.url" controls preload="metadata" @error="previewError='音频预览失败，请下载后用本机播放器打开'"/><video v-else class="preview-video" :src="previewData.url" controls preload="metadata" playsinline @loadedmetadata="previewMetadata" @error="previewError='当前播放源无法解码，请下载完成后再次预览，或定位原文件用本机播放器打开'"/></template><div class="modal-actions"><button @click="closeModal">关闭预览</button></div></template>
  <template v-else-if="modal==='rename'"><p>将对 {{renameIds.length}} 项{{renameMode==='jobs'?'下载记录及已完成文件':'资源标题'}}应用命名模板。</p><div class="field"><label for="rename-template">命名模板</label><input id="rename-template" v-model="renameTemplate" placeholder="{platform} - {title}"/><p>{title} 标题 · {author} 作者 · {platform} 平台 · {date} 日期 · {index} 序号。扩展名与已有同名文件自动处理。</p></div><p class="modal-hint">未完成的任务不会移动文件；更改后续下载的默认命名，可在设置中保存命名模板。</p><div class="modal-actions"><button @click="closeModal" :disabled="busy">取消</button><button class="primary" @click="renameSelected" :disabled="busy||!renameTemplate.trim()"><Pencil :size="17"/>应用命名</button></div></template>
  <template v-else-if="modal==='duplicate'"><p>发现 {{duplicateRequests.length}} 个已有的已完成下载。可以定位文件，也可以明确选择重新下载。</p><div class="duplicate-list"><article v-for="item in duplicateRequests" :key="item.id"><div><strong>{{item.name}}</strong><span>{{item.message||'该内容已有已完成文件'}}</span></div><button v-if="item.jobId" class="compact" @click="locateDuplicate(item)"><FolderOpen :size="15"/>定位文件</button></article></div><div class="modal-actions"><button @click="closeModal">跳过重复项</button><button class="primary" @click="forceDuplicates" :disabled="busy"><RefreshCw :size="17"/>重新下载这些内容</button></div></template>
  <template v-else-if="modal==='onboarding'"><div class="onboarding-dots"><i v-for="n in 3" :key="n" :class="{active:onboardingStep===n-1}"></i></div><div v-if="onboardingStep===0" class="onboarding-content"><div class="onboarding-icon"><CheckCheck :size="36"/></div><h3>先看看运行环境</h3><p>下载引擎、视频处理工具与保存目录会在本机检查。无需先打开捕获，也能直接添加公开视频链接。</p><button class="compact" @click="checkEnvironment" :disabled="!!maintenanceBusy"><RefreshCw :size="15"/>{{maintenanceBusy==='check'?'正在检查…':'重新检查'}}</button><div v-if="selfCheck" class="self-check-list"><div v-for="item in selfCheck.items||selfCheck.checks||[]" :key="item.id" :class="item.status"><CheckCircle2 v-if="['ok','ready','pass'].includes(item.status)" :size="16"/><AlertCircle v-else :size="16"/><strong>{{item.label||item.name}}</strong><span>{{item.message}}</span></div></div></div><div v-else-if="onboardingStep===1" class="onboarding-content"><div class="onboarding-icon"><Link2 :size="36"/></div><h3>添加链接，或捕获正在播放的内容</h3><p>分享文本可以直接粘贴，每次最多 100 条链接。微信视频号请先开始捕获，再在电脑版微信打开并播放目标视频。</p><p>开启 HTTPS 捕获时，会提示安装本机证书。停止捕获或正常退出会恢复系统代理。</p></div><div v-else class="onboarding-content"><div class="onboarding-icon"><Download :size="36"/></div><h3>选画质，暂停续传，整理文件</h3><p>点击每条资源选择实际可用的画质。任务中可暂停或继续，完成后直接预览或定位文件。</p><p>保存位置：{{state.config.downloadDir}}。按平台分类、作者分类与命名模板都可以在设置中调整。</p></div><div class="modal-actions"><button v-if="onboardingStep>0" @click="onboardingStep--">上一步</button><button v-if="onboardingStep<2" class="primary" @click="onboardingStep++">下一步<ChevronRight :size="16"/></button><button v-else class="primary" @click="finishOnboarding" :disabled="busy"><Check :size="17"/>开始使用</button></div></template>
  <template v-else><p class="confirmation-copy">{{confirmText}}</p><div class="modal-actions"><button @click="closeModal" :disabled="busy">取消</button><button class="primary" @click="confirm" :disabled="busy"><LoaderCircle v-if="busy" class="spin" :size="18"/>{{busy?'处理中…':confirmAction==='capture'?'开始捕获':'确认'}}</button></div></template>
 </section></div>
</div>
</template>
